SCOPE_SQL="""CREATE FUNCTION b05_statistics_source_scope() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE result jsonb; source_file text; finished text;
BEGIN
  IF NEW.analysis_run_id IS NULL THEN RETURN NEW; END IF;
  SELECT r.result_json::jsonb,r.file_id,r.completed_at INTO result,source_file,finished
    FROM analysis_runs r JOIN files f ON f.id=r.file_id JOIN projects p ON p.id=f.project_id
    WHERE r.id=NEW.analysis_run_id AND f.project_id=NEW.project_id AND p.owner_id=NEW.user_id;
  IF result IS NULL OR nullif(finished,'') IS NULL OR nullif(result->>'completed_at','') IS NULL
    OR result->>'completed_at' IS DISTINCT FROM finished OR result->>'id' IS DISTINCT FROM NEW.analysis_run_id
    OR result->>'file_id' IS DISTINCT FROM source_file THEN
    RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Statistics source project or completion differs';
  END IF;
  IF result->'engine'->>'execution_contract'='fixed_statistics_v2' AND NOT EXISTS(
    SELECT 1 FROM tasks t WHERE t.project_id=NEW.project_id AND t.user_id=NEW.user_id
      AND t.task_type='statistics_compute' AND t.status='succeeded' AND t.result_analysis_run_id=NEW.analysis_run_id
      AND t.input_snapshot->'file'->>'id'=source_file) THEN
    RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Statistics source task incomplete';
  END IF;
  IF EXISTS(SELECT 1 FROM storage_deletion_operations o WHERE o.state<>'preview'
    AND (o.project_id=NEW.project_id AND (o.scope_kind='project' OR o.state IN ('running','partial_failed'))
      OR o.scope_kind='file' AND o.file_id=source_file AND EXISTS(SELECT 1 FROM storage_deletion_items i WHERE i.operation_id=o.id AND i.state<>'retained'))) THEN
    RAISE EXCEPTION USING ERRCODE='P7501',MESSAGE='storage_deletion_pending';
  END IF;
  RETURN NEW;
END $$"""

def upgrade():
    op.execute("SET LOCAL lock_timeout='3s'")
    for table in ('research_source_bindings','manuscript_research_sources'):
        op.execute('ALTER TABLE '+table+' ADD COLUMN analysis_run_id TEXT')
        op.execute('ALTER TABLE '+table+' ADD CONSTRAINT b05_statistics_source_fk FOREIGN KEY(analysis_run_id) REFERENCES analysis_runs(id)')
        op.execute('CREATE INDEX '+table+'_analysis_run_id ON '+table+' (analysis_run_id)')
    for table,old_name,new_name,old_sql,new_sql in CHANGES:
        op.drop_constraint(old_name,table,type_='check');op.create_check_constraint(new_name,table,new_sql)
    op.execute(SCOPE_SQL)
    for table in ('research_source_bindings','manuscript_research_sources'):
        op.execute('CREATE TRIGGER b05_statistics_source_scope BEFORE INSERT ON '+table+' FOR EACH ROW EXECUTE FUNCTION b05_statistics_source_scope()')

def downgrade():
    raise RuntimeError('Statistics source history requires a reviewed restore; immutable bindings preserved.')
